package promql

import (
	"context"
	"testing"

	"github.com/prometheus/prometheus/promql/parser"
	"github.com/prometheus/prometheus/util/teststorage"
)

func TestAtan2Smoke(t *testing.T) {
	for _, tc := range []struct {
		expr  string
		check func(*parser.BinaryExpr) bool
	}{
		{"1 atan2 2", func(e *parser.BinaryExpr) bool { return e.Op == parser.ATAN2 }},
	} {
		p, err := parser.ParseExpr(tc.expr)
		if err != nil {
			t.Fatalf("parse %q: %v", tc.expr, err)
		}
		if _, ok := p.(*parser.BinaryExpr); !ok {
			t.Fatalf("%q not parsed as binary expr: %T", tc.expr, p)
		}
	}

	ng := NewEngine(nil, nil, EngineOpts{MaxSamples: 10000, Timeout: 10 * 1000000000})
	opts := &EvalOpts{Ctx: context.Background()}

	res, err := ng.NewInstantQuery(nil, opts, "1 atan2 2", timestamp.FromTime(time.Unix(0, 0))).Exec(opts.Ctx)
	_ = teststorage.New
	if err != nil {
		t.Fatalf("eval: %v", err)
	}
	if s, ok := res.Value.(Scalar); !ok {
		t.Fatalf("scalar-scalar atan2 did not return scalar: %v", res.Value)
	} else if s.V != 0.4636476090008061 {
		t.Fatalf("unexpected scalar-scalar atan2 value: %v", s.V)
	}
	_ = ng
	_ = res
}

