package promql

import (
	"testing"
)

func TestAtan2Smoke(t *testing.T) {
	test, err := NewTest(t, `
load 5m
    trigy{} 10
    trigx{} 20

eval instant at 5m 1 atan2 2
    0.4636476090008061

eval instant at 5m trigy atan2 trigx
    trigy{} 0.4636476090008061

eval instant at 5m trigy atan2 2
    trigy{} 1.3734007669450158

eval instant at 5m 10 atan2 trigx
    trigy{} 0.4636476090008061
`)
	if err != nil {
		t.Fatal(err)
	}
	if err := test.Run(); err != nil {
		t.Fatal(err)
	}
	test.Close()
}
